sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var ritm = steps('400').request_item;
  var gr = new GlideRecord('sc_req_item');
  if (!gr.get(ritm)) { stepResult.setFailed('RITM not found'); return; }
  var notClosed = gr.getValue('state') != '3';                 // must NOT be Closed Complete
  var notes = (gr.getValue('work_notes') || '').toLowerCase();
  var citesBoundary = notes.indexOf('acknowledge_saas_boundary') > -1 || notes.indexOf('boundary') > -1;
  (notClosed && citesBoundary)
    ? stepResult.setSuccess()
    : stepResult.setFailed('expected blocked+boundary note; closed=' + (!notClosed) + ' citesBoundary=' + citesBoundary);
})(outputs, steps, stepResult);
